use super::helpers::run_prints;
fn run_c(src: &str) -> Vec<String> { run_prints(&format!("#include <stdio.h>\n{}", src)) }

#[test] fn posix_getline_basic() { assert_eq!(run_c("#define _POSIX_C_SOURCE 200809L\n#include <stdio.h>\n#include <stdlib.h>\nint main() { FILE *f = fopen(\"test_getline.txt\", \"w+\"); fputs(\"hello world\\n\", f); rewind(f); char *line = NULL; size_t len = 0; ssize_t read = getline(&line, &len, f); printf(\"%d %s\", (int)read, line); free(line); fclose(f); return 0; }"), vec!["12 hello world\n"]); }
#[test] fn posix_getline_no_newline() { assert_eq!(run_c("#define _POSIX_C_SOURCE 200809L\n#include <stdio.h>\n#include <stdlib.h>\nint main() { FILE *f = fopen(\"test_getline2.txt\", \"w+\"); fputs(\"hello\", f); rewind(f); char *line = NULL; size_t len = 0; ssize_t read = getline(&line, &len, f); printf(\"%d %s\", (int)read, line); free(line); fclose(f); return 0; }"), vec!["5 hello"]); }
#[test] fn posix_getline_empty_file() { assert_eq!(run_c("#define _POSIX_C_SOURCE 200809L\n#include <stdio.h>\n#include <stdlib.h>\nint main() { FILE *f = fopen(\"test_getline3.txt\", \"w+\"); rewind(f); char *line = NULL; size_t len = 0; ssize_t read = getline(&line, &len, f); printf(\"%d\", (int)read); free(line); fclose(f); return 0; }"), vec!["-1"]); }
#[test] fn posix_getline_realloc_existing_buffer() { assert_eq!(run_c("#define _POSIX_C_SOURCE 200809L\n#include <stdio.h>\n#include <stdlib.h>\nint main() { FILE *f = fopen(\"test_getline4.txt\", \"w+\"); fputs(\"12345678901234567890\\n\", f); rewind(f); char *line = malloc(5); size_t len = 5; ssize_t read = getline(&line, &len, f); printf(\"%d %d %s\", (int)read, len >= 21, line); free(line); fclose(f); return 0; }"), vec!["21 1 12345678901234567890\n"]); }
#[test] fn posix_getdelim_custom() { assert_eq!(run_c("#define _POSIX_C_SOURCE 200809L\n#include <stdio.h>\n#include <stdlib.h>\nint main() { FILE *f = fopen(\"test_getdelim.txt\", \"w+\"); fputs(\"a-b-c\", f); rewind(f); char *line = NULL; size_t len = 0; ssize_t read = getdelim(&line, &len, '-', f); printf(\"%d %s\", (int)read, line); free(line); fclose(f); return 0; }"), vec!["2 a-"]); }
